/**
 * `relationMode = "prisma"` against the real generated client and real MySQL.
 *
 * The detection pin reads the mode from the two generated MySQL fixtures (the
 * default schema and `prisma-mysql-relation-prisma/schema.prisma`), so a Prisma
 * upgrade that moves `_engineConfig.inlineSchema` fails here rather than
 * silently disarming the refusal. Both clients are generated by the packages
 * shard before its tests; without them the pin skips locally and fails on CI.
 *
 * The MySQL control (MYSQL_URL, a run-unique database dropped afterwards)
 * shows the refusal by name, then, with the refusal bypassed, the race the
 * refusal exists for: two concurrent conditional updates both report success.
 *
 * @module
 */
import { existsSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { PrismaMariaDb } from '@prisma/adapter-mariadb';
import type { EntityKey } from '@setu-ts/common';
import { relationModeOf } from '../../src/adapters/prisma/prisma-adapter.ts';
import {
  createPrismaDataSource,
  UnsupportedQueryFeatureError,
  UnsupportedRelationModeError,
  updateVersioned,
} from '../../src/index.ts';
import { mysqlHarness } from '../fixtures/mysql-harness.ts';

const RELATION_PRISMA = 'prisma-client-generated-mysql-relation-prisma';
const clients = {
  default: new URL('../fixtures/prisma-client-generated-mysql/client.ts', import.meta.url),
  prisma: new URL(`../fixtures/${RELATION_PRISMA}/client.ts`, import.meta.url),
};
const generated = existsSync(clients.default) && existsSync(clients.prisma);

describe(
  'relationMode detection on the generated client',
  { skip: !generated && process.env['GITHUB_ACTIONS'] !== 'true' },
  () => {
    for (const [mode, expected] of [
      ['prisma', 'prisma'],
      ['default', 'foreignKeys'],
    ] as const) {
      it(`reads ${expected} from the root and an extended client`, async () => {
        const { PrismaClient } = (await import(clients[mode].href)) as {
          PrismaClient: new (options: { adapter: unknown }) => {
            $extends(extension: unknown): unknown;
            $disconnect(): Promise<void>;
          };
        };
        // Constructing the client opens no connection; port 1 is never dialled.
        const client = new PrismaClient({
          adapter: new PrismaMariaDb({ host: '127.0.0.1', port: 1 }),
        });
        const extended = client.$extends({
          query: {
            $allModels: {
              $allOperations: ({
                args,
                query,
              }: {
                args: unknown;
                query: (a: unknown) => unknown;
              }) => query(args),
            },
          },
        });
        expect(relationModeOf(client)).toBe(expected);
        expect(relationModeOf(extended)).toBe(expected);
        // With no assertion, the default client reaches the write's own input check (an
        // empty precondition, refused before I/O) and the "prisma" client is refused first.
        await expect(
          createPrismaDataSource(
            client as unknown as Parameters<typeof createPrismaDataSource>[0],
            'Row',
            'mysql',
          ).deleteWhere!('r', {}),
        ).rejects.toBeInstanceOf(
          mode === 'prisma' ? UnsupportedRelationModeError : UnsupportedQueryFeatureError,
        );
        await client.$disconnect();
      });
    }
  },
);

describe('relationMode "prisma" on real MySQL', { skip: !process.env['MYSQL_URL'] }, () => {
  it('refuses conditional writes by name, and without the refusal both racers win', async () => {
    const h = await mysqlHarness('prisma', 10, RELATION_PRISMA);
    try {
      const repo = h.database.getRepository<{ id: string; version: number; balance: number }>(
        'Row',
      );
      await repo.create({ id: 'refused', version: 1, balance: 0 });
      await expect(repo.updateWhere!('refused', { version: 1 }, { version: 2 })).rejects.toThrow(
        UnsupportedRelationModeError,
      );
      await expect(updateVersioned(repo, 'refused', 1, { balance: 1 })).rejects.toThrow(
        UnsupportedRelationModeError,
      );
      await expect(
        h.database.transaction((uow) =>
          uow.getRepository<Record<string, unknown>, EntityKey>('Row').deleteWhere!('refused', {
            version: 1,
          }),
        ),
      ).rejects.toThrow(UnsupportedRelationModeError);
      expect(await repo.findById('refused')).toMatchObject({ version: 1, balance: 0 });

      // The transaction client reaches the same schema as the root client.
      const client = (
        h.adapter as unknown as {
          _client: { $transaction<T>(fn: (tx: unknown) => Promise<T>): Promise<T> };
        }
      )._client;
      expect(await client.$transaction((tx) => Promise.resolve(relationModeOf(tx)))).toBe('prisma');

      // Bypass the refusal: the predicate Prisma drops lets both racers report a win.
      (h.adapter as unknown as { _relationModeRefusal: undefined })._relationModeRefusal =
        undefined;
      const source = h.adapter.createDataSource('Row') as {
        updateWhere(
          id: string,
          where: Record<string, number>,
          data: Record<string, number>,
        ): Promise<Record<string, unknown> | null>;
      };
      // A forced interleaving, not a timing race: a second connection holds an uncommitted
      // version change on the row. Prisma's plain SELECT still reads version 1 and its UPDATE
      // by id waits on the row lock; once the change commits, a predicated UPDATE would match
      // nothing, but Prisma's emulated one overwrites the committed version and reports a win.
      await repo.create({ id: 'held', version: 1, balance: 0 });
      const other = await h.pool.getConnection();
      try {
        await other.query('START TRANSACTION');
        await other.query('UPDATE `rows` SET version = 5 WHERE id = ?', ['held']);
        const call = source.updateWhere('held', { version: 1 }, { version: 2, balance: 1 });
        await new Promise((resolve) => setTimeout(resolve, 700));
        await other.query('COMMIT');
        expect(await call).not.toBeNull();
      } finally {
        other.release();
      }
      // The committed version 5 was overwritten by a write whose precondition no longer held.
      expect(await repo.findById('held')).toMatchObject({ version: 2, balance: 1 });
    } finally {
      await h.dispose();
    }
  }, 60_000);
});
